using System;
using System.Collections.Generic;
using UnityEngine;

namespace BTP.Plants
{
    /// <summary>
    /// Plant ID to PlantVillage sample leaf images and disease names for the Farm disease gallery.
    /// Regenerated by Build Plant Assets (DiseaseGalleryBuilder); never wired by hand.
    /// </summary>
    [CreateAssetMenu(menuName = "BTP/Disease Gallery Catalog", fileName = "DiseaseGalleryCatalog")]
    public sealed class DiseaseGalleryCatalog : ScriptableObject
    {
        [Serializable]
        public sealed class Entry
        {
            public string id;
            public string displayName;
            public Texture2D leaf;
        }

        [Serializable]
        sealed class PlantEntries
        {
            public string plantId;
            public List<Entry> diseases = new List<Entry>();
        }

        [SerializeField] List<PlantEntries> plants = new List<PlantEntries>();

        static readonly IReadOnlyList<Entry> None = Array.Empty<Entry>();

        public int TotalCount
        {
            get
            {
                var total = 0;
                foreach (var plant in plants)
                    total += plant.diseases.Count;
                return total;
            }
        }

        /// <summary>The diseases of one plant; an empty list for an unknown ID.</summary>
        public IReadOnlyList<Entry> GetDiseases(string plantId)
        {
            foreach (var plant in plants)
            {
                if (plant.plantId == plantId)
                    return plant.diseases;
            }

            return None;
        }

        internal void Clear() => plants.Clear();

        internal void Add(string plantId, string diseaseId, string displayName, Texture2D leaf)
        {
            var group = plants.Find(p => p.plantId == plantId);
            if (group == null)
            {
                group = new PlantEntries { plantId = plantId };
                plants.Add(group);
            }

            group.diseases.Add(new Entry { id = diseaseId, displayName = displayName, leaf = leaf });
        }
    }
}
